// Start Run: normalise whichever trigger fired into one run context.
const input = $input.first().json || {};
let trigger = 'manual';
if (input.trigger) trigger = String(input.trigger);          // called by the dashboard
else if (input.timestamp || input['Readable date']) trigger = 'schedule';

const tz = $env.GENERIC_TIMEZONE || $env.TZ || 'UTC';
const now = new Date();
const weekday = new Intl.DateTimeFormat('en-US', { weekday: 'short', timeZone: tz }).format(now);
const dow = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].indexOf(weekday);

return [{
  json: {
    run: {
      run_id: `pipe-${$execution.id}`,
      execution_id: $execution.id,
      trigger,
      started_at: now.toISOString(),
      tz,
      dow,
      force_type: input.force_type || null,   // optional override from the dashboard ("article", "package"...)
    },
  },
}];

// Sitemap Targets: which PlacidWay sitemaps feed the candidate pool.
// Sitemaps are the politest source available: one request per content type,
// already sorted by lastmod, explicitly published for crawlers in robots.txt.
const base = ($env.PW_BASE_URL || 'https://www.placidway.com').replace(/\/$/, '');
const ctx = $('Start Run').first().json;
const targets = [
  { type: 'article', url: `${base}/1/sitemap_articles.xml` },
  { type: 'package', url: `${base}/1/sitemap_packages.xml` },
  { type: 'answer',  url: `${base}/sitemap/1/sitemap_answers.xml` },
  { type: 'news',    url: `${base}/1/sitemap_news.xml` },
];
return targets.map((t) => ({ json: { ...ctx, target: t } }));

// Pick Candidate: parse sitemaps, drop anything already used, apply variety
// rules, and choose exactly one URL for today.
// ---- inlined from lib/categories.js ----
// Shared: treatment-category classifier used for variety rules and hashtags.
// Inlined into Code nodes at build time (see tools/build-workflows.mjs).
const CATEGORY_RULES = [
  ['Stem Cell & Regenerative', /stem[- ]?cell|regenerative|prp|exosome|mesenchymal/i],
  ['Cancer Care', /cancer|oncolog|tumou?r|chemo|radiother|immunother|car[- ]?t\b|leukemia|lymphoma/i],
  ['Bariatric & Weight Loss', /bariatric|gastric|sleeve|bypass|obesity|weight[- ]loss|ozempic|mounjaro|glp[- ]?1|semaglutide|tirzepatide/i],
  ['Cosmetic & Plastic Surgery', /cosmetic|plastic|tummy|abdominoplast|liposuc|lipo\b|breast|rhinoplast|facelift|bbl|butt[- ]lift|body[- ]contour|mommy[- ]makeover|blepharo|eyelid/i],
  ['Dental Care', /dental|dentist|implant|veneer|crown|all[- ]on[- ]?\d|teeth|tooth|smile/i],
  ['Fertility & IVF', /ivf|fertility|surrogacy|egg[- ]donat|icsi|infertil/i],
  ['Orthopedics & Spine', /orthop|knee|hip|spine|spinal|shoulder|joint|arthro|disc\b|scoliosis/i],
  ['Cardiology', /cardi|heart|bypass[- ]surgery|valve|angioplast/i],
  ['Hair Restoration', /hair[- ]?(transplant|restoration|loss)|fue\b|dhi\b/i],
  ['Eye Care', /lasik|eye|cataract|ophthalm|vision/i],
  ['Neurology', /neuro|parkinson|alzheimer|autism|multiple[- ]sclerosis|\bms\b|stroke|cerebral[- ]palsy|huntington|als\b/i],
  ['Health Checkups', /check[- ]?up|screening|assessment|executive[- ]health|wellness/i],
  ['Anti-Aging & Wellness', /anti[- ]?aging|longevity|iv[- ]therapy|nad\+?|detox|spa\b/i],
  ['Urology', /urolog|prostate|erectile|kidney|ed\b/i],
  ['Diabetes', /diabet/i],
];

function classifyCategory(text) {
  const s = String(text || '').replace(/[-_]/g, ' ');
  for (const [name, re] of CATEGORY_RULES) if (re.test(s)) return name;
  return 'Medical Travel';
}

// Strip the directory and id from a PlacidWay URL to get a readable title guess.
function titleFromUrl(url) {
  const last = String(url).split('?')[0].replace(/\/$/, '').split('/').pop() || '';
  return decodeURIComponent(last).replace(/-/g, ' ').replace(/\s+/g, ' ').trim();
}

function normalizeUrl(url) {
  try {
    const u = new URL(String(url).trim());
    u.hash = '';
    u.search = '';
    u.hostname = u.hostname.toLowerCase().replace(/^placidway\.com$/, 'www.placidway.com');
    u.protocol = 'https:';
    return u.toString().replace(/\/$/, '');
  } catch (e) {
    return String(url).trim();
  }
}
// ---- end lib/categories.js ----
const ctx = $('Start Run').first().json;
const state = $('Load Settings').first().json;
const settings = state.settings || {};
const used = new Set((state.used_urls || []).map(normalizeUrl));
const recent = state.recent || [];
const targets = $('Sitemap Targets').all().map((i) => i.json.target);
const responses = $input.all();

const POOL_PER_TYPE = 60;
const avoidN = Number(settings.avoid_recent_categories || 3);
const recentCategories = recent.slice(0, avoidN).map((r) => r.category).filter(Boolean);
const lastType = recent[0] && recent[0].content_type;

let rotation = {};
try { rotation = JSON.parse(settings.rotation || '{}'); } catch (e) { rotation = {}; }
const todaysType = ctx.run.force_type || rotation[String(ctx.run.dow)] || 'article';

function parseSitemap(xml, type) {
  const out = [];
  const re = /<url>([\s\S]*?)<\/url>/g;
  let m;
  while ((m = re.exec(xml))) {
    const block = m[1];
    const loc = (block.match(/<loc>\s*([^<]+?)\s*<\/loc>/) || [])[1];
    if (!loc) continue;
    const lastmod = (block.match(/<lastmod>\s*([^<]+?)\s*<\/lastmod>/) || [])[1] || '';
    const image = (block.match(/<image:loc>\s*([^<]+?)\s*<\/image:loc>/) || [])[1] || null;
    const newsTitle = (block.match(/<news:title>\s*([^<]+?)\s*<\/news:title>/) || [])[1] || null;
    const id = Number((loc.match(/\/(\d+)\//) || [])[1] || 0);
    out.push({ url: normalizeUrl(loc), type, lastmod, image, id, title_guess: newsTitle || titleFromUrl(loc) });
  }
  return out;
}

const pools = {};
const poolSizes = {};
responses.forEach((r, i) => {
  const type = targets[i] && targets[i].type;
  if (!type) return;
  const xml = typeof r.json.data === 'string' ? r.json.data : '';
  const all = parseSitemap(xml, type);
  // Freshest first: lastmod, then id (PlacidWay ids are monotonic, and lastmod alone is noisy
  // because old pages get touched).
  all.sort((a, b) => (b.lastmod.localeCompare(a.lastmod)) || (b.id - a.id));
  const fresh = all.slice(0, POOL_PER_TYPE).filter((c) => !used.has(c.url));
  fresh.forEach((c) => { c.category = classifyCategory(c.title_guess + ' ' + c.url); });
  pools[type] = fresh;
  poolSizes[type] = { in_sitemap: all.length, fresh_unused: fresh.length };
});

if (!Object.values(poolSizes).some((p) => p.in_sitemap > 0)) {
  throw new Error('All PlacidWay sitemaps came back empty or unparseable: site may be down or markup changed');
}

function score(c, rank) {
  let s = 100 - rank;                                    // freshness
  if (recentCategories.includes(c.category)) s -= 60;   // category variety
  if (c.image) s += 5;                                  // prefer items with a featured image
  if (c.title_guess.length < 20) s -= 10;               // thin slugs tend to be thin pages
  return s;
}

function best(list) {
  return list
    .map((c, rank) => ({ c, s: score(c, rank) }))
    .sort((a, b) => b.s - a.s)[0];
}

let chosen = null;
let reason = '';
const primary = pools[todaysType] && pools[todaysType].length ? best(pools[todaysType]) : null;
if (primary) {
  chosen = primary.c;
  reason = ctx.run.force_type
    ? `Dashboard requested "${todaysType}"`
    : `Rotation picks "${todaysType}" for ${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][ctx.run.dow]}`;
} else {
  // Fallback: any other type, avoiding yesterday's type when possible.
  const fallbacks = Object.keys(pools).filter((t) => t !== todaysType && pools[t].length);
  fallbacks.sort((a, b) => (a === lastType) - (b === lastType));
  for (const t of fallbacks) { const b = best(pools[t]); if (b) { chosen = b.c; break; } }
  reason = chosen ? `No fresh "${todaysType}" item; fell back to "${chosen.type}"` : 'Nothing fresh to post';
}
if (chosen && recentCategories.includes(chosen.category)) reason += ` (category "${chosen.category}" repeats: no alternative)`;
else if (chosen) reason += `; category "${chosen.category}" not used in last ${avoidN} posts`;

return [{
  json: {
    ...ctx,
    settings,
    found: !!chosen,
    item: chosen,
    selection: { reason, todays_type: todaysType, recent_categories: recentCategories, pools: poolSizes },
  },
}];

// Extract Content: turn the fetched page into a clean, bounded source record.
// Strategy: JSON-LD first (PlacidWay publishes Article / Product / BlogPosting /
// FAQPage / BreadcrumbList on every page), Open Graph second, stripped HTML last.
// ---- inlined from lib/categories.js ----
// Shared: treatment-category classifier used for variety rules and hashtags.
// Inlined into Code nodes at build time (see tools/build-workflows.mjs).
const CATEGORY_RULES = [
  ['Stem Cell & Regenerative', /stem[- ]?cell|regenerative|prp|exosome|mesenchymal/i],
  ['Cancer Care', /cancer|oncolog|tumou?r|chemo|radiother|immunother|car[- ]?t\b|leukemia|lymphoma/i],
  ['Bariatric & Weight Loss', /bariatric|gastric|sleeve|bypass|obesity|weight[- ]loss|ozempic|mounjaro|glp[- ]?1|semaglutide|tirzepatide/i],
  ['Cosmetic & Plastic Surgery', /cosmetic|plastic|tummy|abdominoplast|liposuc|lipo\b|breast|rhinoplast|facelift|bbl|butt[- ]lift|body[- ]contour|mommy[- ]makeover|blepharo|eyelid/i],
  ['Dental Care', /dental|dentist|implant|veneer|crown|all[- ]on[- ]?\d|teeth|tooth|smile/i],
  ['Fertility & IVF', /ivf|fertility|surrogacy|egg[- ]donat|icsi|infertil/i],
  ['Orthopedics & Spine', /orthop|knee|hip|spine|spinal|shoulder|joint|arthro|disc\b|scoliosis/i],
  ['Cardiology', /cardi|heart|bypass[- ]surgery|valve|angioplast/i],
  ['Hair Restoration', /hair[- ]?(transplant|restoration|loss)|fue\b|dhi\b/i],
  ['Eye Care', /lasik|eye|cataract|ophthalm|vision/i],
  ['Neurology', /neuro|parkinson|alzheimer|autism|multiple[- ]sclerosis|\bms\b|stroke|cerebral[- ]palsy|huntington|als\b/i],
  ['Health Checkups', /check[- ]?up|screening|assessment|executive[- ]health|wellness/i],
  ['Anti-Aging & Wellness', /anti[- ]?aging|longevity|iv[- ]therapy|nad\+?|detox|spa\b/i],
  ['Urology', /urolog|prostate|erectile|kidney|ed\b/i],
  ['Diabetes', /diabet/i],
];

function classifyCategory(text) {
  const s = String(text || '').replace(/[-_]/g, ' ');
  for (const [name, re] of CATEGORY_RULES) if (re.test(s)) return name;
  return 'Medical Travel';
}

// Strip the directory and id from a PlacidWay URL to get a readable title guess.
function titleFromUrl(url) {
  const last = String(url).split('?')[0].replace(/\/$/, '').split('/').pop() || '';
  return decodeURIComponent(last).replace(/-/g, ' ').replace(/\s+/g, ' ').trim();
}

function normalizeUrl(url) {
  try {
    const u = new URL(String(url).trim());
    u.hash = '';
    u.search = '';
    u.hostname = u.hostname.toLowerCase().replace(/^placidway\.com$/, 'www.placidway.com');
    u.protocol = 'https:';
    return u.toString().replace(/\/$/, '');
  } catch (e) {
    return String(url).trim();
  }
}
// ---- end lib/categories.js ----
const ctx = $('Pick Candidate').first().json;
const claimed = $('Claim URL').first().json;
const html = String($input.first().json.data || '');

const MAX_BODY = 6000;

function decode(s) {
  return String(s || '')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#0?39;|&apos;|&#x27;/g, "'")
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&rsquo;|&lsquo;/g, "'").replace(/&rdquo;|&ldquo;/g, '"')
    .replace(/&ndash;/g, '-').replace(/&mdash;/g, '-').replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)));
}
function strip(s) {
  return decode(String(s || '')
    .replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>|<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<\/(p|li|h[1-6]|div|tr|br)>/gi, '\n').replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, ' '))
    .replace(/[ \t]+/g, ' ').replace(/\s*\n\s*/g, '\n').replace(/\n{2,}/g, '\n').trim();
}
function meta(prop) {
  const re = new RegExp(`<meta[^>]+(?:property|name)=["']${prop}["'][^>]*content=["']([^"']*)["']`, 'i');
  const re2 = new RegExp(`<meta[^>]+content=["']([^"']*)["'][^>]*(?:property|name)=["']${prop}["']`, 'i');
  const m = html.match(re) || html.match(re2);
  return m ? decode(m[1]).trim() : null;
}

// ---- JSON-LD ----
const ld = [];
const ldRe = /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
let m;
while ((m = ldRe.exec(html))) {
  try {
    const parsed = JSON.parse(m[1].trim().replace(/[\u0000-\u001f]+/g, ' '));
    const flat = [].concat(parsed).flatMap((d) => (d && d['@graph'] ? d['@graph'] : [d]));
    ld.push(...flat.filter(Boolean));
  } catch (e) { /* malformed block: skip, fall back to OG/HTML */ }
}
const byType = (t) => ld.find((d) => [].concat(d['@type']).includes(t));

const article = byType('Article') || byType('NewsArticle') || byType('BlogPosting') || byType('MedicalWebPage');
const product = byType('Product');
const webpage = byType('WebPage');
const faqPage = byType('FAQPage');
const crumbs = byType('BreadcrumbList');

const title = decode(
  (article && (article.headline || article.name)) || (product && product.name) ||
  meta('og:title') || (html.match(/<title>([^<]*)/i) || [])[1] || ctx.item.title_guess
).trim();

const summary = decode(
  (webpage && webpage.description) || (article && article.description) || (product && product.description) ||
  meta('og:description') || meta('description') || ''
).trim();

// Body text: structured first, then the main content region.
let body = '';
if (article && article.articleBody) body = decode(article.articleBody);
if (!body || body.length < 300) {
  const region = html.match(/class="[^"]*(pack-inner-content|article-dt-desc|answer-detail|news-detail|ctm-dt-pages)[^"]*"[\s\S]{0,120000}/i);
  if (region) body = strip(region[0]).slice(0, MAX_BODY * 2);
}
if (!body) body = summary;
body = body.replace(/\s+\n/g, '\n').trim();

// Price facts are only ever copied from structured offers or the page itself.
const priceFacts = [];
if (product && product.offers) {
  for (const o of [].concat(product.offers)) {
    const price = o.price || o.lowPrice;
    if (price) priceFacts.push(`${o.priceCurrency || ''} ${price}${o.highPrice ? ' - ' + o.highPrice : ''}`.trim());
  }
}

const faqs = faqPage && Array.isArray(faqPage.mainEntity)
  ? faqPage.mainEntity.slice(0, 5).map((q) => ({
      q: decode(q.name),
      a: decode(strip(q.acceptedAnswer && q.acceptedAnswer.text)).slice(0, 400),
    }))
  : [];

let category = null;
if (crumbs && Array.isArray(crumbs.itemListElement)) {
  const names = crumbs.itemListElement.map((c) => decode(c.name || (c.item && c.item.name) || '')).filter(Boolean);
  // Home > Medical Articles > <Category> > Title
  const cand = names.slice(2, -1).find((n) => n && !/^all$/i.test(n));
  if (cand && cand.length < 60) category = cand;
}
const categoryGroup = classifyCategory(`${category || ''} ${title} ${ctx.item.url}`);

const ogImage = meta('og:image');
let image = ogImage || (article && article.image && (article.image.url || article.image)) ||
  (product && [].concat(product.image || [])[0]) || ctx.item.image || null;
if (image && typeof image !== 'string') image = image.url || null;
if (image && /logo|placeholder|no[-_]?image/i.test(image)) image = null;

const published = (article && (article.datePublished || article.dateCreated)) || (webpage && webpage.datePublished) || null;

// The exact text the LLM is allowed to use: also stored for audit and for the number check.
const truncated = body.length > MAX_BODY ? body.slice(0, MAX_BODY).replace(/\s+\S*$/, '') + ' ...' : body;
const excerpt = [
  `TITLE: ${title}`,
  summary && `SUMMARY: ${summary}`,
  priceFacts.length && `LISTED PRICE: ${priceFacts.join('; ')}`,
  `BODY:\n${truncated}`,
  faqs.length && `FAQ:\n${faqs.map((f) => `Q: ${f.q}\nA: ${f.a}`).join('\n')}`,
].filter(Boolean).join('\n\n');

if (body.length < 120 && summary.length < 60) {
  throw new Error(`Extraction too thin for ${ctx.item.url}: page markup may have changed`);
}

return [{
  json: {
    ...ctx,
    post_id: claimed.id,
    source: {
      url: ctx.item.url,
      type: ctx.item.type,
      title,
      summary,
      category: category || categoryGroup,
      category_group: categoryGroup,
      image,
      published_at: published,
      price_facts: priceFacts,
      faqs,
      body_chars: body.length,
      excerpt,
      extracted_via: article ? 'json-ld:article' : product ? 'json-ld:product' : 'html',
    },
    attempt: 0,
    attempts_log: [],
    feedback: [],
  },
}];

// Build Prompt: writer prompt + JSON schema. On a retry, the previous
// guardrail findings are fed back so the model fixes exactly what failed.
const ctx = $json;
const attempt = (ctx.attempt || 0) + 1;
const s = ctx.source;

const system = `You are the social media writer for PlacidWay, a medical tourism marketplace that helps patients compare treatments, clinics and packages abroad.

Voice: warm, clear, trustworthy, patient-first. Informative, never hype. Plain English at roughly an 8th-grade reading level.

Hard rules (a compliance checker will reject the post if any is broken):
1. Use ONLY facts that appear in the SOURCE. No outside knowledge, no statistics, prices, durations, success rates, names or credentials that are not in the SOURCE.
2. No medical claims or promises of outcomes. Never say or imply: cure, guaranteed, permanent results, risk-free, painless, no side effects, miracle, proven, reverses, eliminates, best/top/#1. Use hedged, patient-education language ("may", "patients often ask", "learn what to consider").
3. Never invent or estimate prices. Mention a price only if it appears verbatim in the SOURCE, written exactly as the SOURCE writes it, and frame it as "listed" or "starting" exactly as the source does.
4. Every value line must be backed by a short verbatim quote from the SOURCE, which you return in "claims".
5. Do not include the URL or hashtags inside hook/lines/cta. They are added separately.
6. At most one emoji in the hook and none elsewhere.`;

const feedback = (ctx.feedback || []).length
  ? `\n\nYOUR PREVIOUS DRAFT WAS REJECTED. Fix every issue below and do not repeat them:\n${ctx.feedback.map((f, i) => `${i + 1}. ${f}`).join('\n')}\n`
  : '';

const prompt = `Write one Facebook post promoting the PlacidWay page below.

Format requirements:
- hook: one scroll-stopping opening line (max 110 characters), a question or a curiosity gap grounded in the source.
- lines: 2 to 4 short value lines (max 90 characters each) a reader learns from the page.
- cta: one call to action inviting people to read the full guide / view the package / compare options on PlacidWay (max 80 characters).
- hashtags: 3 to 5 relevant hashtags, CamelCase, no spaces, without the URL. Include one treatment tag and one destination tag when the source names a destination.
- claims: for each value line, the verbatim SOURCE quote (8-30 words) that supports it.
- Total of hook + lines + cta must be under 430 characters.

CONTENT TYPE: ${s.type}
CATEGORY: ${s.category}
SOURCE URL: ${s.url}

SOURCE:
"""
${s.excerpt}
"""${feedback}`;

const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['hook', 'lines', 'cta', 'hashtags', 'claims'],
  properties: {
    hook: { type: 'string' },
    lines: { type: 'array', items: { type: 'string' }, minItems: 2, maxItems: 4 },
    cta: { type: 'string' },
    hashtags: { type: 'array', items: { type: 'string' }, minItems: 3, maxItems: 5 },
    claims: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['line', 'source_quote'],
        properties: { line: { type: 'string' }, source_quote: { type: 'string' } },
      },
    },
  },
};

return {
  json: {
    ...ctx,
    attempt,
    llm_request: {
      model: $env.LLM_MODEL_WRITER || 'sonnet',
      system,
      prompt,
      schema,
      tag: `${ctx.run.run_id}:write:${attempt}`,
    },
  },
};

// Assemble Post: deterministic formatting around the LLM's parts, so the
// structure (hook / value lines / CTA / link / hashtags) is guaranteed by code.
// ---- inlined from lib/guardrails.js ----
// Shared: post assembly + deterministic guardrails.
// Used by the pipeline (after generation) and by the dashboard API (when a
// reviewer edits a draft), so a human edit is held to the same rules.

const BODY_LIMIT = 500; // characters before the link, per the brief

function buildLink(url, utm) {
  if (!utm) return url;
  return url + (url.includes('?') ? '&' : '?') + utm;
}

function cleanTag(t) {
  const core = String(t || '').replace(/^#+/, '').replace(/[^\p{L}\p{N}]+/gu, '');
  return core ? `#${core}` : null;
}

function assemblePost(gen, sourceUrl, utm) {
  const hook = String(gen.hook || '').trim();
  const lines = (gen.lines || []).map((l) => String(l).trim().replace(/^[-•*✅▸]\s*/, '')).filter(Boolean);
  const cta = String(gen.cta || '').trim();
  const hashtags = [...new Set((gen.hashtags || []).map(cleanTag).filter(Boolean))];
  const link = buildLink(sourceUrl, utm);
  const body = [hook, '', ...lines.map((l) => `• ${l}`), '', cta].join('\n');
  const text = `${body}\n👉 ${link}\n\n${hashtags.join(' ')}`;
  return { hook, lines, cta, hashtags, link, body, text, body_chars: [...body].length };
}

// Split an edited full post back into parts so edits get the same checks.
function parsePostText(text, sourceUrl) {
  const t = String(text || '');
  const linkMatch = t.match(/https?:\/\/\S+/);
  const link = linkMatch ? linkMatch[0] : '';
  const idx = linkMatch ? t.indexOf(link) : t.length;
  const body = t.slice(0, idx).replace(/👉\s*$/u, '').trimEnd();
  const after = t.slice(idx + link.length);
  const hashtags = (after.match(/#[\p{L}\p{N}_]+/gu) || []);
  const parts = body.split('\n').map((s) => s.trim()).filter(Boolean);
  const hook = parts[0] || '';
  const bulletLines = parts.filter((p) => /^[•\-*✅▸]/.test(p)).map((p) => p.replace(/^[•\-*✅▸]\s*/, ''));
  const cta = parts.length > 1 ? parts[parts.length - 1] : '';
  return { hook, lines: bulletLines, cta, hashtags, link, body, text: t, body_chars: [...body].length, source_url: sourceUrl };
}

// Medical-claim language that must never appear, regardless of source wording.
const BANNED = [
  [/\bcur(e|es|ed|ing)\b/i, 'promises a cure'],
  [/\bguarantee(d|s)?\b/i, 'guarantees an outcome'],
  [/\b100\s?%/i, 'absolute (100%) claim'],
